void kvm_recalculate_apic_map(struct kvm *kvm)
{
    struct kvm_apic_map *old_map = kvm->apic_map;
    struct kvm_apic_map *new_map;
    int i;

    new_map = kzalloc(sizeof(*new_map), GFP_KERNEL);
    if (!new_map)
        return;

    mutex_lock(&kvm->apic_map_lock);

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm->vcpus[i];

        if (!vcpu)
            continue;

        if (vcpu->apic->base_address & APIC_LVR_DIRECTED_EOI) {
            /* x2APIC mode */
            new_map->phys_id_map[vcpu->vcpu_id] = vcpu->arch.apic_id;
            new_map->logical_id_map[vcpu->arch.apic_id] = vcpu->vcpu_id;
            new_map->version = APIC_X2APIC_VERSION;
        } else {
            /* xAPIC mode */
            new_map->phys_id_map[vcpu->vcpu_id] = vcpu->arch.apic_id;
            new_map->logical_id_map[vcpu->arch.apic_id] = vcpu->vcpu_id;
            new_map->version = APIC_XAPIC_VERSION;
        }
    }

    kvm->apic_map = new_map;
    kfree(old_map);

    mutex_unlock(&kvm->apic_map_lock);

    kvm_ioapic_scan_entry(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_apic_map;
    int i;

    new_apic_map = kzalloc(sizeof(*new_apic_map), GFP_KERNEL);
    if (!new_apic_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
