        if (vcpu->arch.apic_mode == XAPIC) {
            new_apic_map->logical_id[vcpu->vcpu_id] = vcpu->arch.apic->logical_id;
        } else if (vcpu->arch.apic_mode == X2APIC) {
            new_apic_map->logical_id[vcpu->vcpu_id] = vcpu->arch.apic->x2apic_id;
        }
    }

    kvm->apic_map = new_apic_map;
    spin_unlock(&kvm->apic_map_lock);

    kvm_ioapic_scan_all(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_map;
    int i;

    new_map = kmalloc(sizeof(*new_map), GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    new_map->max_apic_id = 0;
    new_map->logical_id_to_apic_id = 0;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm->vcpus[i];
        if (!vcpu)
            continue;

        if (vcpu->apic->mode == APIC_XAPIC) {
            new_map->phys_id = vcpu->apic->phys_id;
            new_map->logical_id = vcpu->apic->logical_id;
        } else if (vcpu->apic->mode == APIC_X2APIC) {
            new_map->phys_id = vcpu->apic->x2apic_id;
            new_map->logical_id = vcpu->apic->logical_id;
        }

        new_map->max_apic_id = max(new_map->max_apic_id, vcpu->apic->phys_id);
    }

    kvm->apic_map = new_map;
    spin_unlock(&kvm->apic_map_lock);

    kvm_free_old_apic_map(kvm);
    kvm_ioapic_scan_all(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_apic_map;
    int i;

    new_apic_map = kzalloc(sizeof(*new_apic_map), GFP_KERNEL);
    if (!new_apic_map)
        return;

    spin_lock(&kvm->apic_map_lock);
    kvm->apic_map = new_apic_map;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm_get_vcpu(kvm, i);
        if (!vcpu)
            continue;

        if (vcpu->arch.apic->base_address & (1 << 10)) {
            /* x2APIC mode */
            kvm_apic_set_x2apic_mode(new_apic_map, vcpu->vcpu_id);
        } else {
            /* xAPIC mode */
            kvm_apic_set_xapic_mode(new_apic_map, vcpu->vcpu_id);
        }
    }

    kvm_apic_build_logical_id(new_apic_map, kvm);
    kvm->apic_map_version++;

    spin_unlock(&kvm->apic_map_lock);

    kvm_free_old_apic_map(kvm);
    kvm_ioapic_scan(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_apic_map;
    int i;

    new_apic_map = kzalloc(sizeof(*new_apic_map), GFP_KERNEL);
    if (!new_apic_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    new_apic_map->max_apic_id = 0;
    new_apic_map->phys_apic_ids = NULL;
    new_apic_map->logical_apic_ids = NULL;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm_get_vcpu(kvm, i);
        if (!vcpu)
            continue;

        if (vcpu->apic->base_address & (1 << 11)) {
            /* x2APIC mode */
            new_apic_map->logical_apic_ids[vcpu->vcpu_id] = vcpu->apic->base_address & 0xff;
        } else {
            /* xAPIC mode */
            new_apic_map->logical_apic_ids[vcpu->vcpu_id] = vcpu->apic->base_address & 0xff;
        }

        new_apic_map->phys_apic_ids[vcpu->vcpu_id] = vcpu->apic->apic_id;
        new_apic_map->max_apic_id = max(new_apic_map->max_apic_id, vcpu->apic->apic_id);
    }

    kvm->apic_map = new_apic_map;
    spin_unlock(&kvm->apic_map_lock);

    kvm_free_apic_map(kvm->old_apic_map);
    kvm->old_apic_map = NULL;

    kvm_ioapic_scan_entry(kvm);
}
